mapper.select:



        and tsr.session_id in
        #{id}

     and tsr.session_id = #{sessionId}
     and tsr.student_id = #{studentId}
     and st.student_code = #{studentCode}
     and st.student_name like concat('%', #{studentName}, '%')

        and (st.student_code like concat('%', #{keyword}, '%')
            or st.student_name like concat('%', #{keyword}, '%'))

     and ts.talk_type = #{talkType}
     and ts.talk_person like concat('%', #{talkPerson}, '%')
     and ts.talk_time >= #{beginTalkTime}
     and ts.talk_time < date_add(#{endTalkTime}, interval 1 day)

        and exists (
            select 1 from talk_session_tag tst
            where tst.session_id = tsr.session_id
              and (

                    (tst.tag_value = #{tagValue}
                     or (json_valid(tst.tag_value) and json_contains(tst.tag_value, json_quote(#{tagValue}))))

              )
        )

     and tsr.student_feedback = #{studentFeedback}
     and (tsr.student_feedback is null or tsr.student_feedback = '' or tsr.student_feedback = '无')
     and tsr.followup_plan = #{followupPlan}
     and tsr.followup_status = #{followupStatus}
     and tsr.notified = #{notified}
     and tsr.teacher_notified = #{teacherNotified}
     and ts.college_dept_id = #{params.collegeDeptId}

order by ts.talk_time desc, tsr.record_id desc

mapper.update:
update talk_student_record
session_id = #{sessionId}, student_id = #{studentId}, student_feedback = #{studentFeedback}, original_student_feedback = #{originalStudentFeedback}, followup_plan = #{followupPlan}, followup_status = #{followupStatus}, notified = #{notified}, teacher_notified = #{teacherNotified}, update_time = #{updateTime},
where record_id = #{recordId}

mapper.select:


     and ts.college_dept_id = #{collegeDeptId}

order by tsr.create_time desc
limit 8
